## Show that strings interacting with the read-chunk boundary are reported
## correctly. The input files are crafted assuming the native read chunk size
## (sys::fs::DefaultReadChunkSize) of 16384 bytes.
##
## The inputs, and expected output lines too long to write as CHECK lines, are
## generated by the script at the end of this file.

## Case 1: at least min string size appears before the boundary, unprintable
## byte as first byte of the next chunk. The string is printed on its own,
## with the offset of its start (16376 = 16384 - 8).
# RUN: %python %s 16376 ENDCHUNK 4 > %t.1
# RUN: llvm-strings --radix=d %t.1 | FileCheck %s --check-prefix=CASE1 --match-full-lines --strict-whitespace --implicit-check-not={{.}}

# CASE1:  16376 ENDCHUNK

## Case 2: at least min string size appears before the boundary, printable
## byte as first byte of the next chunk. The prefix is printed together with
## the following characters, as a single string.
# RUN: %python %s 16378 BEFORE AFTER! 4 > %t.2
# RUN: llvm-strings --radix=d %t.2 | FileCheck %s --check-prefix=CASE2 --match-full-lines --strict-whitespace --implicit-check-not={{.}}

# CASE2:  16378 BEFOREAFTER!

## Case 3: less than min string size appears before the boundary, unprintable
## byte as the next byte. The prefix is not printed.
# RUN: %python %s 16382 AB 4 > %t.3
# RUN: llvm-strings %t.3 | count 0

## Case 4: less than min string size appears before the boundary, printable
## bytes as the next bytes, forming a min length string. The prefix is
## printed together with the following characters, with the offset of its
## true start (16381 = 16384 - 3).
# RUN: %python %s 16381 ABC DEF 4 > %t.4
# RUN: llvm-strings --radix=d %t.4 | FileCheck %s --check-prefix=CASE4 --match-full-lines --strict-whitespace --implicit-check-not={{.}}

# CASE4:  16381 ABCDEF

## Case 5: the prefix is empty at the start of a chunk that starts with a min
## length string (16384).
# RUN: %python %s 16384 FRESH 4 > %t.5
# RUN: llvm-strings --radix=d %t.5 | FileCheck %s --check-prefix=CASE5 --match-full-lines --strict-whitespace --implicit-check-not={{.}}

# CASE5:  16384 FRESH

## Case 6: a string that spans the entirety of one chunk, with one character
## before the chunk start and one after its end. The string is printed
## intact, once. The expected output is generated rather than written as a
## CHECK line because it is a chunk long.
# RUN: %python %s 16383 S M E 4 --repeat 1,1,16384,1,1 > %t.6
# RUN: %python %s --line S M E --repeat 1,16384,1 > %t.6.expected
# RUN: llvm-strings %t.6 > %t.6.out
# RUN: diff %t.6.expected %t.6.out

## Case 7: the minimum length is greater than the chunk size, so a candidate
## has to be buffered across more than one chunk before it is known to be long
## enough. A run of exactly the minimum length is printed, with the offset of
## its start, which lies in an earlier chunk than the one where it is printed.
# RUN: %python %s 8 A 4 --repeat 1,20000,1 > %t.7
# RUN: %python %s --line --offset=8 A --repeat 20000 > %t.7.expected
# RUN: llvm-strings --radix=d --bytes=20000 %t.7 > %t.7.out
# RUN: diff %t.7.expected %t.7.out

## Case 8: as case 7, but the run is one byte short of the minimum length, so
## the buffered candidate is discarded and nothing is printed.
# RUN: %python %s 8 A 4 --repeat 1,19999,1 > %t.8
# RUN: llvm-strings --bytes=20000 %t.8 | count 0

## Case 9: a string is terminated by the end of the file, with no trailing
## unprintable byte. The string must still be printed.
# RUN: %python %s 16380 TRAILING > %t.9
# RUN: llvm-strings %t.9 | FileCheck %s --check-prefix=CASE9 --match-full-lines --strict-whitespace --implicit-check-not={{.}}

# CASE9:TRAILING

import argparse
import sys

parser = argparse.ArgumentParser(description="Write the concatenation of PARTs.")
parser.add_argument(
    "parts",
    nargs="*",
    metavar="PART",
    help="a number, for that many zero bytes, or else literal text",
)
parser.add_argument(
    "--repeat",
    type=lambda arg: [int(n) for n in arg.split(",")] if arg else [],
    default=[],
    help="comma-separated number of times to write each PART (default: once)",
)
parser.add_argument(
    "--line",
    action="store_true",
    help="write the PARTs as a single line of llvm-strings output",
)
parser.add_argument(
    "--offset",
    type=int,
    help="with --line, precede the line with OFFSET as printed by --radix=d",
)
args = parser.parse_intermixed_args()

repeat = args.repeat or [1] * len(args.parts)
if len(repeat) != len(args.parts):
    parser.error(
        "--repeat has %d counts for %d PARTs" % (len(repeat), len(args.parts))
    )

out = b"".join(
    (b"\0" * int(part) if part.isdigit() else part.encode()) * count
    for part, count in zip(args.parts, repeat)
)
if args.line:
    if args.offset is not None:
        out = b"%7d " % args.offset + out
    out += b"\n"
# Write bytes, not text, so that "\n" is not written as "\r\n" on Windows.
sys.stdout.buffer.write(out)
